window.MarcHelperShared = window.MarcHelperShared || {};
window.MarcHelperShared.filler = function (chrome, fetch, importScripts) {
function dispatchChange(element) {
  ['input', 'change', 'blur'].forEach(eventName => {
    const event = new Event(eventName, {bubbles: true});
    element.dispatchEvent(event);
  });
}

function highlightField(element) {
  if (!element) return;
  element.style.transition = 'box-shadow 0.3s ease, background-color 0.3s ease';
  element.style.boxShadow = '0 0 0 3px rgba(34, 197, 94, 0.35)';
  element.style.backgroundColor = '#f0fdf4';
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

/**
 * Koha renders each MARC field occurrence as <li class="tag" id="tag_650_XXXX">
 * (addbiblio.tt; older versions used <div class="tag">). Returns them in page order.
 */
function getTagBlocks(tag) {
  return Array.from(document.querySelectorAll(`li.tag[id^="tag_${tag}_"], div.tag[id^="tag_${tag}_"]`));
}

function subfieldSelector(tag, code) {
  const prefix = code ? `tag_${tag}_subfield_${code}_` : `tag_${tag}_subfield_`;
  return `input[id^="${prefix}"]:not([type="hidden"]), textarea[id^="${prefix}"], select[id^="${prefix}"]`;
}

/**
 * Find the input for subfield `code` in occurrence `index` of `tag`.
 * `codeIndex` selects a repeated subfield within the same field.
 */
function findSubfieldInput(tag, code, index = 1, codeIndex = 1) {
  const blocks = getTagBlocks(tag);
  if (blocks.length > 0) {
    const block = blocks[index - 1];
    if (!block) return null;
    return Array.from(block.querySelectorAll(subfieldSelector(tag, code)))[codeIndex - 1] || null;
  }

  // Fallback for layouts without div.tag wrappers: only the first occurrence is addressable
  if (index !== 1) return null;
  return Array.from(document.querySelectorAll(subfieldSelector(tag, code)))[codeIndex - 1] || null;
}

function setInputValue(input, value) {
  input.value = value;
  // A <select> silently ignores values that are not among its options
  if (input.tagName === 'SELECT' && input.value !== value) return false;
  dispatchChange(input);
  highlightField(input);
  return true;
}

function setIndicator(tag, indicator, value, index = 1) {
  const blocks = getTagBlocks(tag);
  const scope = blocks.length > 0 ? blocks[index - 1] : (index === 1 ? document : null);
  if (!scope) return false;
  const el = scope.querySelector(`input[name^="tag_${tag}_indicator${indicator}"], input[id^="tag_${tag}_indicator${indicator}"], select[name^="tag_${tag}_indicator${indicator}"]`);
  if (!el) return false;
  return setInputValue(el, value || ' ');
}

/**
 * Click Koha's "Repeat this tag" control on the last occurrence of `tag`
 * and wait for the new block to appear.
 */
async function repeatTag(tag) {
  const blocks = getTagBlocks(tag);
  const last = blocks[blocks.length - 1];
  if (!last) return false;

  const button = Array.from(last.querySelectorAll('a, button')).find(node => {
    if (node.closest('.subfield_line')) return false;  // skip per-subfield clone buttons
    const title = (node.title || node.getAttribute('aria-label') || '').toLowerCase();
    const onclick = node.getAttribute('onclick') || '';
    return title.includes('repeat this tag') || onclick.includes('CloneField') || node.classList.contains('buttonPlus');
  });
  if (!button) return false;

  button.click();
  for (let i = 0; i < 20; i++) {
    await sleep(100);
    if (getTagBlocks(tag).length > blocks.length) return true;
  }
  return false;
}

/**
 * Repeat a subfield inside one field occurrence (e.g. several 505 $t or 043 $a):
 * clicks the "+" of the last existing input for that code (Koha's CloneSubfield)
 * and waits for the new input.
 */
async function repeatSubfield(tag, code, index) {
  const blocks = getTagBlocks(tag);
  const block = blocks.length > 0 ? blocks[index - 1] : (index === 1 ? document : null);
  if (!block) return false;
  const inputs = Array.from(block.querySelectorAll(subfieldSelector(tag, code)));
  const line = inputs.length ? inputs[inputs.length - 1].closest('.subfield_line') : null;
  if (!line) return false;

  const button = Array.from(line.querySelectorAll('a, button')).find(node =>
    (node.getAttribute('onclick') || '').includes('CloneSubfield') || node.classList.contains('buttonPlus'));
  if (!button) return false;

  button.click();
  for (let i = 0; i < 20; i++) {
    await sleep(100);
    if (block.querySelectorAll(subfieldSelector(tag, code)).length > inputs.length) return true;
  }
  return false;
}

/**
 * The control fields Koha requires before it saves (000 leader, 003, 005, 008 in the default
 * framework) are not written from the record: an empty box gets focus once, as with a click,
 * and Koha's own value builders fill it (000 the default leader, 003 the MARCOrgCode system
 * preference, 005 the time, 008 the default with today's date).
 * A box that already has a value is left as it is.
 */
async function fillControlFields(record) {
  const input = tag => document.querySelector(`input[id^="tag_${tag}_subfield_"]:not([type="hidden"]), textarea[id^="tag_${tag}_subfield_"]`);
  // 000 and 008 are left to Koha (library policy): its own builders write them, as with one click
  const scroll = window.scrollY;
  for (const tag of ['000', '003', '005', '008']) {
    const element = input(tag);
    if (!element || element.value.trim()) continue;
    element.dispatchEvent(new Event('focus'));
    element.focus();
    await sleep(150);
    element.blur();
  }
  window.scrollTo(0, scroll);
}

async function populateFields(record) {
  const errors = [];
  const tagCounts = {};
  await fillControlFields(record);

  for (const field of record.fields || []) {
    const tag = field.tag;
    if (!tag || tag === '008') continue;

    tagCounts[tag] = (tagCounts[tag] || 0) + 1;
    const tagIndex = tagCounts[tag];

    // Make sure a block exists for this occurrence (650, 700, … repeats)
    const blocks = getTagBlocks(tag);
    if (blocks.length > 0 && blocks.length < tagIndex) {
      const added = await repeatTag(tag);
      if (!added) {
        errors.push(`Could not add occurrence ${tagIndex} of ${tag} (use "Repeat this tag" manually)`);
        continue;
      }
    }

    if (parseInt(tag) < 10) {
      const input = findSubfieldInput(tag, '', tagIndex);
      if (!input || !field.value || !setInputValue(input, field.value)) {
        errors.push(`Could not populate control field ${tag}`);
      }
      continue;
    }

    setIndicator(tag, 1, field.indicators?.[0] || ' ', tagIndex);
    setIndicator(tag, 2, field.indicators?.[1] || ' ', tagIndex);

    const codeCounts = {};
    for (const subfield of field.subfields || []) {
      const code = Object.keys(subfield)[0];
      const value = subfield[code];
      if (!code || value === undefined || value === null || value === '') continue;

      codeCounts[code] = (codeCounts[code] || 0) + 1;
      let input = findSubfieldInput(tag, code, tagIndex, codeCounts[code]);
      // A repeated subfield needs another input: use Koha's subfield repeat
      if (!input && codeCounts[code] > 1 && await repeatSubfield(tag, code, tagIndex)) {
        input = findSubfieldInput(tag, code, tagIndex, codeCounts[code]);
      }
      if (!input || !setInputValue(input, value)) {
        errors.push(`Could not populate ${tag}$${code} (occurrence ${tagIndex})`);
      }
    }
  }

  const saveButton = document.querySelector('button[name="save"]') ||
                     document.querySelector('input[name="save"]') ||
                     document.querySelector('#addbiblio #save');
  if (saveButton) {
    saveButton.classList.add('koha-populated-highlight');
    saveButton.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }

  return errors;
}

// --- The library's authority file, for Check headings (read only) ---
// Requests go to this Koha (same origin) with the cataloguer's own staff login; only these
// three: the Koha MARC Helper plugin's lookup, the staff authority search, one authority record.
// Firefox: content.fetch makes the request as the page, so the login cookie goes with it.
const pageFetch = (typeof content !== 'undefined' && content && typeof content.fetch === 'function')
  ? (...args) => content.fetch(...args) : (...args) => fetch(...args);
const looksLikeLogin = html => /id="loginform"|name="koha_login_context"|<body[^>]*id="main_auth"/.test(html);

async function kohaAuthorities(message) {
  if (message.op === 'plugin') {
    const token = document.querySelector('meta[name="csrf-token"]');
    const res = await pageFetch('/api/v1/contrib/marchelper/authorities', {method: 'POST', credentials: 'same-origin',
      headers: {'Content-Type': 'application/json', Accept: 'application/json', ...(token ? {'CSRF-TOKEN': token.content} : {})},
      body: JSON.stringify({headings: message.headings || []})});
    if (res.status === 404) return {success: false, noPlugin: true};
    if (!res.ok) return {success: false, noPlugin: true, error: `HTTP ${res.status}`};
    const answer = await res.json();
    return {success: true, route: 'plugin', results: answer.results || []};
  }
  if (message.op === 'search') {
    const params = new URLSearchParams({op: 'do_search', type: 'intranet', authtypecode: String(message.authtypecode || ''),
      marclist: 'match', and_or: 'and', excluding: '', operator: 'exact', value: String(message.value || ''), orderby: 'HeadingAsc'});
    const res = await pageFetch(`/cgi-bin/koha/authorities/authorities-home.pl?${params}`, {credentials: 'same-origin'});
    const html = await res.text();
    if (!res.ok || looksLikeLogin(html)) return {success: false, error: 'Koha\'s authority search needs a staff login with catalogue permission.'};
    return {success: true, html};
  }
  if (message.op === 'record') {
    const id = parseInt(message.authid, 10);
    if (!id) return {success: false, error: 'No authority number'};
    const isMarc = xml => /<(?:\w+:)?datafield\b/.test(xml);
    try {   // Koha's REST API (23.05 and later)
      const res = await pageFetch(`/api/v1/authorities/${id}`, {credentials: 'same-origin', headers: {Accept: 'application/marcxml+xml'}});
      if (res.ok) { const xml = await res.text(); if (isMarc(xml)) return {success: true, xml}; }
    } catch (error) { /* the export page below */ }
    const res = await pageFetch(`/cgi-bin/koha/authorities/export.pl?format=marcxml&op=export&authid=${id}`, {credentials: 'same-origin'});
    const xml = await res.text();
    return res.ok && isMarc(xml) ? {success: true, xml} : {success: false, error: `Authority ${id} could not be read`};
  }
  return {success: false, error: 'Unknown request'};
}

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.action !== 'kohaAuthorities') return;
  kohaAuthorities(message).then(sendResponse).catch(error => sendResponse({success: false, error: error.message}));
  return true;
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.action !== 'fillKoha') return;
  populateFields(message.record)
    .then(errors => {
      if (errors.length === 0) {
        sendResponse({success: true});
      } else {
        sendResponse({success: false, error: errors.join('; ')});
      }
    })
    .catch(error => {
      console.error("Population error:", error);
      sendResponse({success: false, error: error.message});
    });
  return true;
});

;return {populateFields, getTagBlocks, findSubfieldInput};
};
